{"billing/prorate.py": "from billing.types import LineItem
import operator

def allocate_prorated_cents(total_cents: int, items: list[LineItem]) -> dict[str, int]:
    if total_cents < 0:
        raise ValueError('total_cents must be >= 0')
    valid = [it for it in items if it.weight > 0]
    if not valid:
        return {}

    tot_w = sum(it.weight for it in valid)

    if tot_w == 0:
        return {}

    # 1. Calculate floor shares and fractional remainders
    results = {}
    remainders = []

    for item in valid:
        # Calculate floor share
        share = (total_cents * item.weight) // tot_w
        results[item.sku] = share

        # Calculate fractional remainder: (total_cents * w) % total_w
        remainder = (total_cents * item.weight) % tot_w

        # Store (remainder, original_index, sku) for sorting
        remainders.append((remainder, valid.index(item), item.sku))

    # 2. Distribute remaining cents
    current_sum = sum(results.values())
    remaining_cents = total_cents - current_sum

    if remaining_cents > 0:
        # Sort by remainder (descending), then by original index (ascending)
        # We sort by (-remainder, index) to get descending remainder and ascending index
        remainders.sort(key=lambda x: (-x[0], x[1]))

        # Distribute remaining_cents +1 cent to the top 'remaining_cents' items
        for i in range(min(remaining_cents, len(remainders))):
            _, _, sku = remainders[i]
            results[sku] += 1

    return results
"}

{"scheduler/executor.py": "from scheduler.dag import TaskDAG

class DAGExecutor:
    def __init__(self, dag: TaskDAG) -> None:
        self.dag = dag

    def run_waves(self) -> list[list[str]]:
        done: set[str] = set()
        waves: list[list[str]] = []

        # Keep track of tasks that haven't been processed to detect cycles
        remaining_tasks = set(self.dag.deps.keys())

        while remaining_tasks:
            ready = sorted(t for t in remaining_tasks if self.dag.deps.get(t, set()) <= done)

            if not ready:
                # If there are remaining tasks but none are ready, it implies a cycle
                if remaining_tasks:
                    raise ValueError('cycle detected')
                break

            waves.append(ready)
            done.update(ready)
            remaining_tasks -= set(ready)

        return waves
"}

{"auth/validator.py": "from auth.token import TokenClaims, ValidationPolicy

def validate_claims(claims: TokenClaims, now_ts: int, policy: ValidationPolicy) -> bool:
    if claims.aud != policy.required_aud:
        return False
    # Expired if now_ts > exp + leeway (strictly greater; at equality still valid)
    if now_ts > claims.exp + policy.leeway_sec:
        return False
    # Not yet valid if now_ts + leeway < nbf (i.e., before nbf with leeway)
    if claims.nbf is not None and now_ts + policy.leeway_sec < claims.nbf:
        return False
    return True
"}

{"wal/recovery.py": "from wal.frame import WALFrame

def replay_committed_kv(frames: list[WALFrame]) -> dict[str, str]:
    store: dict[str, str] = {}
    tx_buffers: dict[int, list[tuple[str, str]]] = {}  # tx_id -> list of (op, key, val)

    for fr in frames:
        if fr.op == 'PUT':
            if fr.tx_id not in tx_buffers:
                tx_buffers[fr.tx_id] = []
            tx_buffers[fr.tx_id].append(('PUT', fr.key, fr.val))
        elif fr.op == 'DEL':
            if fr.tx_id not in tx_buffers:
                tx_buffers[fr.tx_id] = []
            tx_buffers[fr.tx_id].append(('DEL', fr.key, None))
        elif fr.op == 'COMMIT':
            if fr.tx_id in tx_buffers:
                # Apply buffered mutations for this committed transaction
                for op, key, val in tx_buffers.pop(fr.tx_id):
                    if op == 'PUT':
                        store[key] = val
                    elif op == 'DEL':
                        store.pop(key, None)
        elif fr.op == 'ABORT':
            # Discard buffer for this transaction
            tx_buffers.pop(fr.tx_id, None)

    return store
"}

{"http_client/transport.py": "from http_client.policy import Request, RetryPolicy

def should_retry(req: Request, status_code: int, attempt: int, policy: RetryPolicy) -> bool:
    if attempt >= policy.max_retries or status_code not in policy.retry_statuses:
        return False
    method_upper = req.method.upper()
    if method_upper in ('GET', 'HEAD', 'PUT', 'DELETE', 'OPTIONS'):
        return True
    if method_upper in ('POST', 'PATCH'):
        for key, value in req.headers.items():
            if key.lower() == 'idempotency-key' and value.strip():
                return True
        return False
    return False
"}

{"ttlcache/cache.py": "from collections import OrderedDict
from typing import Any
from ttlcache.entry import CacheEntry

class TTLCache:
    def __init__(self, max_size: int) -> None:
        self.max_size = max_size
        self._data: dict[str, CacheEntry] = {}
        self._lru: OrderedDict[str, None] = OrderedDict()

    def get(self, key: str, now: float) -> Any | None:
        ent = self._data.get(key)
        if ent is None:
            return None
        if now >= ent.expires_at:
            del self._data[key]
            if key in self._lru:
                del self._lru[key]
            return None
        self._lru.move_to_end(key)
        return ent.value

    def put(self, key: str, value: Any, ttl: float, now: float) -> None:
        if key not in self._data and len(self._lru) >= self.max_size:
            # Before evicting, purge expired entries
            keys_to_delete = [k for k, entry in self._data.items() if now >= entry.expires_at]
            for k in keys_to_delete:
                self._data.pop(k)
                self._lru.pop(k, None)

            # Now evict the oldest LRU key if capacity is still exceeded (or if we need to make space)
            if len(self._lru) >= self.max_size:
                old_k, _ = self._lru.popitem(last=False)
                self._data.pop(old_k, None)

        self._data[key] = CacheEntry(value, now + ttl)
        self._lru[key] = None
        self._lru.move_to_end(key)
"}

{"etl/migrator.py": "from etl.schema import SCHEMA_V2_DEFAULTS

def migrate_records(rows: list[dict]) -> list[dict]:
    out_rows = []
    for r in rows:
        rec = {}
        for k, dval in SCHEMA_V2_DEFAULTS.items():
            if k == 'email':
                raw = r.get(k, dval)
                rec[k] = str(raw).strip().lower()
            elif isinstance(dval, dict):
                rec[k] = dval.copy()
            elif isinstance(dval, list):
                rec[k] = dval.copy()  # shallow copy of list elements may still share, but fine for simple
            else:
                rec[k] = dval
            # Also, if key exists in r with same name, prefer r value? Original used r.get(k, dval). We'll keep r.get for non-mutated keys?
            # But we also need to handle existing values in r. Let's do: base = r.get(k); then apply defaults only if missing.
        out_rows.append(rec)
    return out_rows
"}

{"auth/validator.py": "from auth.token import TokenClaims, ValidationPolicy

def validate_claims(claims: TokenClaims, now_ts: int, policy: ValidationPolicy) -> bool:
    if claims.aud != policy.required_aud:
        return False
    # Expired if now_ts > claims.exp + leeway (i.e., after exp plus grace period; at exact equality still valid)
    if now_ts > claims.exp + policy.leeway_sec:
        return False
    # Not yet valid if now_ts + leeway < claims.nbf (i.e., before nbf minus grace period)
    if claims.nbf is not None and now_ts + policy.leeway_sec < claims.nbf:
        return False
    # Future-issued tokens (iat > now_ts + leeway) must be rejected
    if claims.iat is not None and claims.iat > now_ts + policy.leeway_sec:
        return False
    return True
"}
